pub fn search_emojis(query: &str) -> Vec<&'static str> {
    let q = query.trim().to_lowercase();
    if q.is_empty() {
        return DEFAULT_EMOJIS.to_vec();
    }

    let q_words: Vec<&str> = q.split_whitespace().collect();
    let mut matches: Vec<(i32, usize, &'static str)> = Vec::new();

    for &(emoji, keywords) in EMOJI_SEARCH_ENTRIES {
        let mut total_score = 0;
        let mut all_matched = true;

        for &qw in &q_words {
            let mut word_best = 0;
            for kw in keywords.split_whitespace() {
                if kw == qw {
                    word_best = word_best.max(100);
                } else if kw.starts_with(qw) {
                    word_best = word_best.max(50);
                } else if qw.len() >= 3 && kw.contains(qw) {
                    word_best = word_best.max(10);
                }
            }
            if word_best == 0 {
                all_matched = false;
                break;
            }
            total_score += word_best;
        }

        if all_matched && total_score > 0 {
            let has_skin = emoji.contains('\u{1F3FB}')
                || emoji.contains('\u{1F3FC}')
                || emoji.contains('\u{1F3FD}')
                || emoji.contains('\u{1F3FE}')
                || emoji.contains('\u{1F3FF}');
            let penalty = if has_skin { 5 } else { 0 };
            matches.push((total_score - penalty, emoji.len(), emoji));
        }
    }

    matches.sort_by(|a, b| b.0.cmp(&a.0).then_with(|| a.1.cmp(&b.1)));
    matches.into_iter().map(|(_, _, em)| em).collect()
}
